import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import type { CreateSighting } from "@/lib/sightings";

import { CaptureForm } from "./index";

const DEFAULT_CLOCK = new Date(2026, 7, 11, 14, 5);

function renderCapture(saveSighting: CreateSighting): void {
  render(<CaptureForm now={() => DEFAULT_CLOCK} saveSighting={saveSighting} />);
}

describe("Capture", () => {
  it("defaults to the device's local date and minute", () => {
    renderCapture(vi.fn());

    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByLabelText("Label time")).toHaveValue("14:05");
  });

  it("warns but allows a label time outside store hours", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: true,
      sighting: {
        createdAt: new Date("2026-08-11T19:05:00.000Z"),
        doneness: null,
        id: 1,
        labelDate: "2026-08-11",
        labelMinute: 480,
        updatedAt: new Date("2026-08-11T19:05:00.000Z"),
      },
    });
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "08:00" },
    });
    expect(screen.getByText("Outside store hours")).toBeTruthy();

    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(saveSighting).toHaveBeenCalledWith({
        labelDate: "2026-08-11",
        labelMinute: 480,
      });
    });
    expect(screen.getByText(/Saved label time for August 11, 2026 at 8:00 AM/)).toBeTruthy();
  });

  it("blocks invalid input before save", async () => {
    const saveSighting = vi.fn();
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label date"), {
      target: { value: "2026-02-30" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    expect(screen.getByText("Enter a complete real date.")).toBeTruthy();
    expect(saveSighting).not.toHaveBeenCalled();
  });

  it("prevents duplicate saves while communicating progress", async () => {
    let resolveSave: ((value: Awaited<ReturnType<CreateSighting>>) => void) | undefined;
    const saveSighting = vi.fn(
      () =>
        new Promise<Awaited<ReturnType<CreateSighting>>>((resolve) => {
          resolveSave = resolve;
        })
    );
    renderCapture(saveSighting);

    const saveButton = screen.getByRole("button", { name: "Save label time" });
    fireEvent.click(saveButton);
    fireEvent.click(saveButton);

    expect(saveSighting).toHaveBeenCalledTimes(1);
    expect(screen.getByRole("status")).toHaveTextContent("Saving label time");
    expect(saveButton).toBeDisabled();

    resolveSave?.({
      ok: false,
      message: "Unable to save label time. Check your connection and try again.",
    });
    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent("Unable to save label time");
    });
  });

  it("keeps entered facts available after an initial save failure", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: false,
      message: "Unable to save label time. Check your connection and try again.",
    });
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label date"), {
      target: { value: "2024-02-29" },
    });
    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "20:30" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toBeTruthy();
    });
    expect(screen.getByLabelText("Label date")).toHaveValue("2024-02-29");
    expect(screen.getByLabelText("Label time")).toHaveValue("20:30");
    expect(screen.queryByText("Sighting saved")).toBeNull();
  });
});

import { createServerFn } from "@tanstack/react-start";

import { createSightingInputSchema } from "@/lib/sightings";
import { sightingOperations } from "@/lib/sightings.server";

export const saveSighting = createServerFn({ method: "POST" })
  .inputValidator(createSightingInputSchema)
  .handler(async ({ data }) => sightingOperations.create(data));

import { sql } from "drizzle-orm";
import {
  check,
  date,
  desc,
  index,
  integer,
  pgTable,
  smallint,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

export const sightings = pgTable(
  "sightings",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    labelDate: date("label_date", { mode: "string" }).notNull(),
    labelMinute: smallint("label_minute").notNull(),
    doneness: text(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    check("sightings_label_minute_check", sql`${table.labelMinute} between 0 and 1439`),
    check("sightings_doneness_check", sql`${table.doneness} in ('light', 'medium', 'dark')`),
    index("sightings_recent_idx").on(desc(table.createdAt), desc(table.id)),
  ]
);

export type Sighting = typeof sightings.$inferSelect;

import { z } from "zod";

export const DONENESS_VALUES = ["light", "medium", "dark"] as const;

export const createSightingInputSchema = z.object({
  labelDate: z.iso.date(),
  labelMinute: z.int().min(0).max(1439),
});

export type CreateSightingInput = z.infer<typeof createSightingInputSchema>;

export type Sighting = {
  createdAt: Date;
  doneness: (typeof DONENESS_VALUES)[number] | null;
  id: number;
  labelDate: string;
  labelMinute: number;
  updatedAt: Date;
};

export type CreateSightingResult =
  | { ok: true; sighting: Sighting }
  | { message: string; ok: false };

export type CreateSighting = (input: CreateSightingInput) => Promise<CreateSightingResult>;

export const SAVE_FAILURE_MESSAGE =
  "Unable to save label time. Check your connection and try again.";

import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { saveSighting } from "@/lib/sighting-functions";
import {
  createSightingInputSchema,
  type CreateSighting,
  type CreateSightingInput,
  type Sighting,
} from "@/lib/sightings";

export const Route = createFileRoute("/")({
  component: CapturePage,
});

type LabelTime = {
  labelDate: string;
  labelTime: string;
};

function padTimePart(value: number): string {
  return value.toString().padStart(2, "0");
}

export function getDeviceLabelTime(date: Date): LabelTime {
  return {
    labelDate: `${date.getFullYear()}-${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`,
    labelTime: `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`,
  };
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = /^(?<hour>[01]\d|2[0-3]):(?<minute>[0-5]\d)$/.exec(labelTime);
  if (!match?.groups) {
    return undefined;
  }

  return Number(match.groups.hour) * 60 + Number(match.groups.minute);
}

function isOutsideStoreHours(labelMinute: number | undefined): boolean {
  return labelMinute !== undefined && (labelMinute < 9 * 60 || labelMinute > 20 * 60);
}

function formatSavedLabelTime(sighting: Sighting): string {
  const date = new Date(`${sighting.labelDate}T12:00:00`);
  const hour = Math.floor(sighting.labelMinute / 60);
  const minute = sighting.labelMinute % 60;
  const time = new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(2000, 0, 1, hour, minute));
  const formattedDate = new Intl.DateTimeFormat("en-US", {
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(date);

  return `Saved label time for ${formattedDate} at ${time}.`;
}

export function CapturePage() {
  const save = useServerFn(saveSighting);

  return <CaptureForm saveSighting={save} />;
}

export function CaptureForm({
  now = () => new Date(),
  saveSighting,
}: Readonly<{
  now?: () => Date;
  saveSighting: CreateSighting;
}>) {
  const [labelTime, setLabelTime] = useState<LabelTime>(() => getDeviceLabelTime(now()));
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isSaving, setIsSaving] = useState(false);
  const [savedSighting, setSavedSighting] = useState<Sighting>();

  useEffect(() => {
    setLabelTime(getDeviceLabelTime(now()));
  }, [now]);

  const labelMinute = labelTimeToMinute(labelTime.labelTime);
  const outsideStoreHours = isOutsideStoreHours(labelMinute);

  const handleSave = async (): Promise<void> => {
    if (isSaving) {
      return;
    }

    if (labelMinute === undefined) {
      setErrorMessage("Enter a complete clock time.");
      return;
    }

    const input: CreateSightingInput = {
      labelDate: labelTime.labelDate,
      labelMinute,
    };
    const validation = createSightingInputSchema.safeParse(input);
    if (!validation.success) {
      setErrorMessage("Enter a complete real date.");
      return;
    }

    setErrorMessage(undefined);
    setIsSaving(true);
    const result = await saveSighting(validation.data);
    setIsSaving(false);

    if (!result.ok) {
      setErrorMessage(result.message);
      return;
    }

    setSavedSighting(result.sighting);
  };

  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">Chicken Tracking</p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Capture</h1>
        <p className="mt-2 text-muted-foreground">Record the label time exactly as printed.</p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Label time</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-6">
            <div className="grid gap-2">
              <Label htmlFor="label-time">Label time</Label>
              <Input
                aria-describedby={outsideStoreHours ? "store-hours-warning" : undefined}
                className="h-16 text-3xl"
                id="label-time"
                onChange={(event) => {
                  setLabelTime((current) => ({ ...current, labelTime: event.target.value }));
                }}
                required
                type="time"
                value={labelTime.labelTime}
              />
              {outsideStoreHours ? (
                <p className="text-sm text-warning-foreground" id="store-hours-warning">
                  Outside store hours
                </p>
              ) : null}
            </div>
            <div className="grid gap-2">
              <Label htmlFor="label-date">Label date</Label>
              <Input
                id="label-date"
                onChange={(event) => {
                  setLabelTime((current) => ({ ...current, labelDate: event.target.value }));
                }}
                required
                type="date"
                value={labelTime.labelDate}
              />
            </div>
            {errorMessage ? (
              <p aria-live="assertive" className="text-destructive text-sm" role="alert">
                {errorMessage}
              </p>
            ) : null}
            {isSaving ? <p aria-live="polite" role="status">Saving label time…</p> : null}
            {savedSighting ? (
              <p aria-live="polite" className="text-success-foreground" role="status">
                {formatSavedLabelTime(savedSighting)}
              </p>
            ) : null}
            <Button className="h-12 text-base" disabled={isSaving} onClick={handleSave} type="button">
              Save label time
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import type { NodePgDatabase } from "drizzle-orm/node-postgres";

import { db } from "@/lib/db";
import { sightings } from "@/lib/db/schema";
import {
  SAVE_FAILURE_MESSAGE,
  type CreateSighting,
  type CreateSightingInput,
  type CreateSightingResult,
  type Sighting,
} from "@/lib/sightings";

type Database = NodePgDatabase<typeof import("@/lib/db/schema")>;

function toSighting(record: typeof sightings.$inferSelect): Sighting {
  return {
    ...record,
    doneness: record.doneness as Sighting["doneness"],
  };
}

export function createSightingOperations(database: Database): {
  create: CreateSighting;
} {
  return {
    create: async (input: CreateSightingInput): Promise<CreateSightingResult> => {
      try {
        const [record] = await database.insert(sightings).values(input).returning();

        if (!record) {
          return { message: SAVE_FAILURE_MESSAGE, ok: false };
        }

        return { ok: true, sighting: toSighting(record) };
      } catch {
        return { message: SAVE_FAILURE_MESSAGE, ok: false };
      }
    },
  };
}

export const sightingOperations = createSightingOperations(db);

